// ==================== Drag & Drop (Pointer Events, desktop + мобильные) ====================
function setupDnD(){
  let active = null; // { li, ul, fill, offsetY, targetIndex }

  const rankInUl = (li) => Array.from(li.parentElement.querySelectorAll(":scope > .item")).indexOf(li);

  function refreshRanks(ul){
    ul.querySelectorAll(":scope > .item").forEach((it, i) => {
      const r = it.querySelector(".rank");
      if (r) r.textContent = i + 1;
    });
  }

  panesEl.addEventListener("pointerdown", (e) => {
    if (e.button !== undefined && e.button !== 0) return;
    if (active) return;
    const li = e.target.closest(".item");
    if (!li) return;
    const pane = li.closest(".pane");
    const ul = li.closest(".list");
    if (!pane || !ul || !pane.classList.contains("is-active")) return;

    const cs = getComputedStyle(ul);
    const gapPx = parseFloat(cs.rowGap || cs.gap) || 8;
    const rect = li.getBoundingClientRect();
    const offsetY = e.clientY - rect.top;

    // заполнитель: резервирует место элемента
    const fill = document.createElement("li");
    fill.className = "fill";
    fill.style.height = (rect.height + gapPx) + "px";
    fill.setAttribute("aria-hidden", "true");
    li.insertAdjacentElement("beforebegin", fill);

    li.classList.add("is-dragging");
    li.style.width = rect.width + "px";
    li.style.left = rect.left + "px";
    li.style.top = rect.top + "px";
    document.body.appendChild(li);

    const targetIndex = rankInUl(li);
    active = { li, ul, fill, offsetY, targetIndex };

    const onMove = (ev) => {
      const a = active;
      if (!a) return;
      a.li.style.top = (ev.clientY - a.offsetY) + "px";

      const center = ev.clientY - a.offsetY + a.li.offsetHeight / 2;
      let idx = 0;
      a.ul.querySelectorAll(":scope > .item").forEach((it) => {
        const r = it.getBoundingClientRect();
        if (center > r.top + r.height / 2) idx++;
      });
      a.targetIndex = idx;

      // перемещаем fill: он должен находиться сразу ПЕРЕД элементом, который в итоге
      // окажется на позиции idx (в текущем списке, где li убран)
      const seq = Array.from(a.ul.children).filter(c => c !== a.fill);
      const before = seq[idx];
      a.fill.remove();
      if (before) before.insertAdjacentElement("beforebegin", a.fill);
      else a.ul.appendChild(a.fill);
    };

    const onUp = (ev) => {
      const a = active;
      if (!a) return;
      if (a.li.hasPointerCapture(ev.pointerId)) a.li.releasePointerCapture(ev.pointerId);
      a.li.removeEventListener("pointermove", onMove);
      a.li.removeEventListener("pointerup", onUp);
      a.li.removeEventListener("pointercancel", onUp);
      a.li.classList.remove("is-dragging");
      a.li.style.cssText = "";
      a.li.remove();
      a.fill.remove();

      const seq = Array.from(a.ul.querySelectorAll(":scope > .item"));
      const before = seq[a.targetIndex];
      if (before) before.insertAdjacentElement("beforebegin", a.li);
      else a.ul.appendChild(a.li);
      refreshRanks(a.ul);
      active = null;
    };

    li.setPointerCapture(e.pointerId);
    li.addEventListener("pointermove", onMove);
    li.addEventListener("pointerup", onUp);
    li.addEventListener("pointercancel", onUp);
  });
}

